I'll create a Terraform module for the three requested resources (S3, RDS, IAM) with environment separation via tfvars, meeting the acceptance criteria.

## Directory Structure

```
.
├── modules/
│   └── app-infra/
│       ├── main.tf
│       ├── s3.tf
│       ├── rds.tf
│       ├── iam.tf
│       ├── variables.tf
│       └── outputs.tf
├── envs/
│   ├── dev.tfvars
│   └── prod.tfvars
├── main.tf
├── variables.tf
├── outputs.tf
├── providers.tf
├── backend.tf
└── .gitignore
```

---

## Module: `modules/app-infra/`

### `variables.tf`

```hcl
variable "environment" {
  description = "Deployment environment (dev/prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
}

variable "tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default     = {}
}

# ---- S3 ----
variable "enable_replication" {
  description = "Enable cross-region replication (prod)"
  type        = bool
  default     = false
}

variable "replication_region" {
  description = "Destination region for CRR"
  type        = string
  default     = "us-west-2"
}

# ---- RDS ----
variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "db_multi_az" {
  description = "Enable Multi-AZ"
  type        = bool
  default     = false
}

variable "db_storage_encrypted" {
  description = "Encrypt RDS storage"
  type        = bool
  default     = true
}

variable "db_backup_retention" {
  description = "Backup retention days (>= 7)"
  type        = number
  default     = 7
  validation {
    condition     = var.db_backup_retention >= 7
    error_message = "backup retention must be >= 7 days."
  }
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username"
  type        = string
  default     = "appadmin"
}

variable "db_password" {
  description = "Master password (injected via -var-file / secret manager, never in Git)"
  type        = string
  sensitive   = true
}

variable "db_subnet_ids" {
  description = "Subnet IDs for the DB subnet group"
  type        = list(string)
}

variable "vpc_id" {
  description = "VPC ID"
  type        = string
}

variable "db_allowed_cidrs" {
  description = "CIDRs allowed to reach the DB (private only)"
  type        = list(string)
  default     = []
}

# ---- IAM ----
variable "oidc_provider_arn" {
  description = "EKS OIDC provider ARN for IRSA trust (prod)"
  type        = string
  default     = ""
}

variable "oidc_provider_url" {
  description = "EKS OIDC provider URL (without https://)"
  type        = string
  default     = ""
}

variable "service_account_namespace" {
  description = "K8s namespace for the service account"
  type        = string
  default     = "default"
}

variable "service_account_name" {
  description = "K8s service account name"
  type        = string
  default     = "app-sa"
}
```

### `main.tf`

```hcl
locals {
  name = "${var.name_prefix}-${var.environment}"
  is_prod = var.environment == "prod"

  common_tags = merge(var.tags, {
    Environment = var.environment
    ManagedBy   = "terraform"
    Module      = "app-infra"
  })
}

data "aws_caller_identity" "current" {}
```

### `s3.tf`

```hcl
resource "aws_s3_bucket" "assets" {
  bucket = "${local.name}-assets-${data.aws_caller_identity.current.account_id}"
  tags   = local.common_tags
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket                  = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---- Cross-region replication (prod only) ----
resource "aws_s3_bucket" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = "${local.name}-assets-replica-${data.aws_caller_identity.current.account_id}"
  tags     = local.common_tags
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0
  name  = "${local.name}-s3-replication"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_replication ? 1 : 0
  name  = "${local.name}-s3-replication"
  role  = aws_iam_role.replication[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
        Resource = [aws_s3_bucket.assets.arn]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging"]
        Resource = ["${aws_s3_bucket.assets.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
        Resource = ["${aws_s3_bucket.replica[0].arn}/*"]
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count      = var.enable_replication ? 1 : 0
  depends_on = [aws_s3_bucket_versioning.assets]
  bucket     = aws_s3_bucket.assets.id
  role       = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-all"
    status = "Enabled"
    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }
  }
}
```

### `rds.tf`

```hcl
resource "aws_db_subnet_group" "this" {
  name       = "${local.name}-db-subnet"
  subnet_ids = var.db_subnet_ids
  tags       = local.common_tags
}

resource "aws_security_group" "db" {
  name        = "${local.name}-db-sg"
  description = "DB access (private only)"
  vpc_id      = var.vpc_id

  ingress {
    description = "PostgreSQL from allowed private CIDRs"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.db_allowed_cidrs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

resource "aws_db_instance" "postgres" {
  identifier     = "${local.name}-postgres"
  engine         = "postgres"
  engine_version = "16"
  instance_class = var.db_instance_class

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = var.db_storage_encrypted

  db_name  = var.db_name
  username = var.db_username
  password = var.db_password

  multi_az               = var.db_multi_az
  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false

  backup_retention_period = var.db_backup_retention
  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "${local.name}-postgres-final"

  auto_minor_version_upgrade = true

  tags = local.common_tags
}
```

### `iam.tf`

```hcl
# Least-privilege policy scoped to this env's bucket
data "aws_iam_policy_document" "app" {
  statement {
    sid    = "S3AssetsAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
    ]
    resources = [
      aws_s3_bucket.assets.arn,
      "${aws_s3_bucket.assets.arn}/*",
    ]
  }
}

resource "aws_iam_policy" "app" {
  name   = "${local.name}-app-policy"
  policy = data.aws_iam_policy_document.app.json
  tags   = local.common_tags
}

# ---- Prod: OIDC/IRSA least-privilege role (no long-lived creds) ----
data "aws_iam_policy_document" "irsa_trust" {
  count = local.is_prod ? 1 : 0
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }
    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:sub"
      values   = ["system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"]
    }
    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "app" {
  count              = local.is_prod ? 1 : 0
  name               = "${local.name}-app-role"
  assume_role_policy = data.aws_iam_policy_document.irsa_trust[0].json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "app" {
  count      = local.is_prod ? 1 : 0
  role       = aws_iam_role.app[0].name
  policy_arn = aws_iam_policy.app.arn
}

# ---- Dev: programmatic IAM user (scoped policy) ----
resource "aws_iam_user" "app" {
  count = local.is_prod ? 0 : 1
  name  = "${local.name}-app-user"
  tags  = local.common_tags
}

resource "aws_iam_user_policy_attachment" "app" {
  count      = local.is_prod ? 0 : 1
  user       = aws_iam_user.app[0].name
  policy_arn = aws_iam_policy.app.arn
}

resource "aws_iam_access_key" "app" {
  count = local.is_prod ? 0 : 1
  user  = aws_iam_user.app[0].name
}
```

### `outputs.tf`

```hcl
output "bucket_name" {
  value = aws_s3_bucket.assets.id
}

output "bucket_arn" {
  value = aws_s3_bucket.assets.arn
}

output "db_endpoint" {
  value = aws_db_instance.postgres.endpoint
}

output "db_connection_string" {
  description = "DB connection string (sensitive)"
  value       = "postgresql://${var.db_username}:${var.db_password}@${aws_db_instance.postgres.endpoint}/${var.db_name}"
  sensitive   = true
}

output "app_role_arn" {
  value       = local.is_prod ? aws_iam_role.app[0].arn : null
  description = "Prod IRSA role ARN"
}

output "app_user_access_key_id" {
  value       = local.is_prod ? null : aws_iam_access_key.app[0].id
  description = "Dev programmatic access key ID"
}

output "app_user_secret_access_key" {
  value     = local.is_prod ? null : aws_iam_access_key.app[0].secret
  sensitive = true
}
```

---

## Root Module

### `providers.tf`

```hcl
terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
  default_tags {
    tags = { Project = "canonical-scenario" }
  }
}

# Replica region provider for CRR
provider "aws" {
  alias  = "replica"
  region = var.replication_region
}
```

### `backend.tf`

```hcl
# State isolation per environment via workspace-keyed key OR separate backend configs.
# Using workspaces: key includes ${terraform.workspace}
terraform {
  backend "s3" {
    bucket = "my-tf-state-bucket"
    key    = "app-infra/terraform.tfstate" # workspace prefixes state automatically
    region = "us-east-1"
    encrypt = true
    dynamodb_table = "tf-locks"
  }
}
```

> With workspaces, state is stored under `env:/<workspace>/app-infra/terraform.tfstate`, giving independent dev/prod state — satisfying criterion 7.

### `variables.tf`

```hcl
variable "region"             { type = string }
variable "replication_region" { type = string, default = "us-west-2" }
variable "environment"        { type = string }
variable "vpc_id"             { type = string }
variable "db_subnet_ids"      { type = list(string) }
variable "db_allowed_cidrs"   { type = list(string) }

variable "db_instance_class"  { type = string }
variable "db_multi_az"        { type = bool }
variable "db_password"        { type = string, sensitive = true }
variable "enable_replication" { type = bool, default = false }

variable "oidc_provider_arn"  { type = string, default = "" }
variable "oidc_provider_url"  { type = string, default = "" }
```

### `main.tf`

```hcl
module "app_infra" {
  source = "./modules/app-infra"
  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  environment = var.environment
  name_prefix = "canonical"

  vpc_id           = var.vpc_id
  db_subnet_ids    = var.db_subnet_ids
  db_allowed_cidrs = var.db_allowed_cidrs

  db_instance_class = var.db_instance_class
  db_multi_az       = var.db_multi_az
  db_password       = var.db_password

  enable_replication = var.enable_replication
  replication_region = var.replication_region

  oidc_provider_arn = var.oidc_provider_arn
  oidc_provider_url = var.oidc_provider_url
}
```

### `outputs.tf`

```hcl
output "bucket_name" { value = module.app_infra.bucket_name }
output "db_endpoint" { value = module.app_infra.db_endpoint }
output "app_role_arn" { value = module.app_infra.app_role_arn }
```

